import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  DirectionalLight,
  RepeatWrapping,
  DoubleSide,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  Color,
} from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

const PLATE_W = 1.9;
const PLATE_H = 1.2;
const PITCH = 1.5;
const COUNT = 6;
const LOOP_LEN = COUNT * PITCH; // 9.0
const COLUMN_X = 0.9;
const HALF_LOOP = LOOP_LEN / 2;

const VARIANT_UV = [
  { offset: [0.0, 0.0], repeat: [0.55, 0.55] },
  { offset: [0.45, 0.0], repeat: [0.55, 0.55] },
  { offset: [0.0, 0.45], repeat: [0.55, 0.55] },
  { offset: [0.45, 0.45], repeat: [0.55, 0.55] },
  { offset: [0.22, 0.22], repeat: [0.55, 0.55] },
  { offset: [0.65, 0.1], repeat: [0.5, 0.5] },
];

const VARIANT_TINT = [
  0xffffff, 0xf2ede6, 0xe8e2da, 0xf0ebe3, 0xe3ddd4, 0xf5f1ea,
];

function wrapY(y) {
  let v = (y + HALF_LOOP) % LOOP_LEN;
  if (v < 0) v += LOOP_LEN;
  return v - HALF_LOOP;
}

function setTreeOpacity(obj, value) {
  obj.traverse((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = value;
      child.material.needsUpdate = true;
    }
  });
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItems = items.filter((i) => i.role === 'caption');
  const headlineText = headlineItem?.text ?? 'Inside the atelier';
  const fallbackCaptions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const group = new Group();
  const disposables = [];
  const tweens = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // Backdrop plane — engineered vertical gradient, no flat voids
  // ---------------------------------------------------------------
  const bgColor1 = new Color(colors.gradientStops?.[0]?.hex ?? colors.background);
  const bgColor2 = new Color(colors.gradientStops?.[1]?.hex ?? colors.surface);
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(bgColor1.r, bgColor1.g, bgColor1.b),
    vec3(bgColor2.r, bgColor2.g, bgColor2.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // Rim / accent light (node-local, opposite the scene key)
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 0.7);
  rimLight.position.set(-2.2, 1.2, -1.5);
  group.add(rimLight);

  // ---------------------------------------------------------------
  // Headline — pinned column header
  // ---------------------------------------------------------------
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper ?? '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0);
  group.add(headline);

  // ---------------------------------------------------------------
  // Loop column of plates
  // ---------------------------------------------------------------
  const columnGroup = new Group();
  group.add(columnGroup);

  const inkColor = new Color(colors.ink ?? '#16161d');
  const accentColor = new Color(colors.accent ?? '#ff2a38');

  const plateDatas = [];

  for (let i = 0; i < COUNT; i++) {
    const plateGroup = new Group();
    const baseY = i * PITCH;

    // machined ink bevel frame
    const frameGeo = new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.05);
    const frameMat = new MeshStandardNodeMaterial({
      color: inkColor,
      roughness: 0.5,
      metalness: 0.5,
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.03;
    plateGroup.add(frame);

    // photograph plate
    const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const plateMat = new MeshPhysicalNodeMaterial({
      color: VARIANT_TINT[i % VARIANT_TINT.length],
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      side: DoubleSide,
    });
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0.001;
    plateGroup.add(plate);

    // accent strip — focus indicator, left edge
    const stripGeo = new BoxGeometry(0.03, PLATE_H, 0.02);
    const stripMat = new MeshStandardNodeMaterial({
      color: accentColor,
      emissive: accentColor,
      emissiveIntensity: 0.0,
      roughness: 0.5,
      metalness: 0.2,
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-PLATE_W / 2 - 0.02, 0, 0.02);
    plateGroup.add(strip);

    // caption — anchored under the column header when focused
    const captionText =
      captionItems[i]?.text ?? fallbackCaptions[i % fallbackCaptions.length];
    const caption = ctx.fontAtlas.createText(captionText, {
      fontSize: 18,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
      letterSpacingPx: 1.4,
    });
    caption.position.set(-1.6 - COLUMN_X, -0.05, 0.05);
    setTreeOpacity(caption, 0);
    plateGroup.add(caption);

    plateGroup.position.set(COLUMN_X, wrapY(baseY), 0);
    columnGroup.add(plateGroup);

    disposables.push(frameGeo, frameMat, plateGeo, plateMat, stripGeo, stripMat);

    plateDatas.push({
      group: plateGroup,
      baseY,
      plateMat,
      stripMat,
      caption,
      focused: false,
      opacityState: { v: 0 },
    });
  }

  // texture load — distinct crops from the single source plate
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.wrapS = RepeatWrapping;
    tex.wrapT = RepeatWrapping;
    plateDatas.forEach((pd, i) => {
      const t = tex.clone();
      t.wrapS = RepeatWrapping;
      t.wrapT = RepeatWrapping;
      const v = VARIANT_UV[i % VARIANT_UV.length];
      t.repeat.set(v.repeat[0], v.repeat[1]);
      t.offset.set(v.offset[0], v.offset[1]);
      t.needsUpdate = true;
      pd.plateMat.map = t;
      pd.plateMat.needsUpdate = true;
      disposables.push(t);
    });
  });

  // ---------------------------------------------------------------
  // Scroll-driven weighted-inertia column motion
  // ---------------------------------------------------------------
  const scrollState = { columnY: 0 };
  let targetColumnY = 0;

  function animateFocus(pd, focusedNow) {
    pd.focused = focusedNow;
    const scaleTarget = focusedNow ? 1.06 : 1.0;
    const t1 = gsap.to(pd.group.scale, {
      x: scaleTarget,
      y: scaleTarget,
      z: scaleTarget,
      duration: 0.35,
      ease: 'power3.out',
    });
    const t2 = gsap.to(pd.stripMat, {
      emissiveIntensity: focusedNow ? 1.4 : 0.0,
      duration: 0.3,
      ease: 'power2.out',
    });
    const t3 = gsap.to(pd.opacityState, {
      v: focusedNow ? 1 : 0,
      duration: focusedNow ? 0.5 : 0.25,
      ease: 'power2.out',
      onUpdate: () => setTreeOpacity(pd.caption, pd.opacityState.v),
    });
    tweens.push(t1, t2, t3);
  }

  function tick() {
    for (const pd of plateDatas) {
      const y = wrapY(pd.baseY - scrollState.columnY);
      pd.group.position.y = y;
      const focusedNow = Math.abs(y) < PITCH / 2;
      if (focusedNow !== pd.focused) {
        animateFocus(pd, focusedNow);
      }
    }
  }
  gsap.ticker.add(tick);

  function onScroll(deltaY = 0) {
    targetColumnY += deltaY * 1.5;
    const t = gsap.to(scrollState, {
      columnY: targetColumnY,
      duration: 0.9,
      ease: 'power4.out',
    });
    tweens.push(t);
  }

  // ---------------------------------------------------------------
  // Entrance
  // ---------------------------------------------------------------
  columnGroup.position.y = 0.3;
  const introTween = gsap.to(columnGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  tweens.push(introTween);
  gsap.set(columnGroup, { opacity: 1 });

  // ---------------------------------------------------------------
  // Cinematic primitives (from config)
  // ---------------------------------------------------------------
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(group, { ...(prim.params ?? {}), trigger: prim.trigger });
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // Handlers + cleanup
  // ---------------------------------------------------------------
  group.userData.handlers = {
    onScroll,
    onWheel: (e) => onScroll(e?.deltaY ? e.deltaY * 0.001 : 0.1),
  };

  group.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    tweens.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    plateDatas.forEach((pd) => {
      pd.caption?.traverse?.((c) => {
        c.geometry?.dispose?.();
        c.material?.dispose?.();
      });
    });
    headline?.traverse?.((c) => {
      c.geometry?.dispose?.();
      c.material?.dispose?.();
    });
  };

  return group;
}
